/**
 * @summary List campaign contacts
 */
export const getListCampaignContactsUrl = (
  businessId: string,
  campaignId: string,
  params?: ListCampaignContactsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/businesses/${businessId}/outbound/campaigns/${campaignId}/contacts?${stringifiedParams}`
    : `/api/businesses/${businessId}/outbound/campaigns/${campaignId}/contacts`;
};

