export const getUpdateFlagUrl = (businessId: string) => {
  return `/api/businesses/${businessId}/flags`;
};

export const updateFlag = async (
  businessId: string,
  updateFlagBody: UpdateFlagBody,
  options?: RequestInit,
): Promise<FeatureFlag> => {
  return customFetch<FeatureFlag>(getUpdateFlagUrl(businessId), {
    ...options,
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(updateFlagBody),
  });
};

export const getUpdateFlagMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof updateFlag>>,
    TError,
    { businessId: string; data: BodyType<UpdateFlagBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof updateFlag>>,
  TError,
  { businessId: string; data: BodyType<UpdateFlagBody> },
  TContext
> => {
  const mutationKey = ["updateFlag"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof updateFlag>>,
    { businessId: string; data: BodyType<UpdateFlagBody> }
  > = (props) => {
    const { businessId, data } = props ?? {};

    return updateFlag(businessId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

